import{_ as e,o as i,c as r,a2 as a}from"./chunks/framework.BZO4qERu.js";const L=JSON.parse('{"title":"AnythingLLM","description":"在 AnythingLLM 中使用 Generic OpenAI Provider 接入 Tokeness。","frontmatter":{"title":"AnythingLLM","description":"在 AnythingLLM 中使用 Generic OpenAI Provider 接入 Tokeness。"},"headers":[],"relativePath":"integrations/anythingllm.md","filePath":"integrations/anythingllm.md","lastUpdated":1781666206000}'),n={name:"integrations/anythingllm.md"};function d(o,t,l,s,h,c){return i(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="anythingllm" tabindex="-1">AnythingLLM <a class="header-anchor" href="#anythingllm" aria-label="Permalink to &quot;AnythingLLM&quot;">​</a></h1><p>AnythingLLM 的 <code>OpenAI (Generic)</code> Provider 用于连接 OpenAI 兼容接口。Tokeness 可以按这个方式接入。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>填写值</th></tr></thead><tbody><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness 控制台创建的 Key</td></tr><tr><td>Model</td><td>从 Tokeness 模型广场复制完整模型名</td></tr></tbody></table><p>AnythingLLM 有桌面版、Docker 版和云端部署方式。菜单位置可能不同，但配置项基本一致。</p><h2 id="配置-llm-provider" tabindex="-1">配置 LLM Provider <a class="header-anchor" href="#配置-llm-provider" aria-label="Permalink to &quot;配置 LLM Provider&quot;">​</a></h2><ol><li>打开 AnythingLLM。</li><li>进入 Settings。</li><li>找到 LLM Preference 或 Model Provider。</li><li>选择 <code>OpenAI (Generic)</code> 或 <code>Generic OpenAI</code>。</li><li>Base URL 填 <code>https://n.tokeness.io/v1</code>。</li><li>API Key 填 Tokeness API Key。</li><li>Model 填 Tokeness 模型广场里的完整模型名。</li><li>保存。</li></ol><p>字段对应：</p><table tabindex="0"><thead><tr><th>AnythingLLM 字段</th><th>Tokeness 填写方式</th></tr></thead><tbody><tr><td>LLM Provider</td><td><code>OpenAI (Generic)</code></td></tr><tr><td>Base URL / API Base</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness API Key</td></tr><tr><td>Model</td><td>Tokeness 模型名</td></tr></tbody></table><h2 id="工作区模型" tabindex="-1">工作区模型 <a class="header-anchor" href="#工作区模型" aria-label="Permalink to &quot;工作区模型&quot;">​</a></h2><p>AnythingLLM 支持按工作区设置模型。全局 Provider 保存后，还要检查当前 Workspace 是否使用了刚配置的模型。</p><p>建议按下面顺序处理：</p><ol><li>先在全局设置里保存 Tokeness Provider。</li><li>进入 Workspace 设置。</li><li>确认 Workspace 使用 Tokeness Provider。</li><li>选择或填写 Tokeness 模型名。</li><li>保存后重新打开对话。</li></ol><p>如果全局能保存，但工作区仍使用旧模型，请检查 Workspace 级别的覆盖设置。</p><h2 id="知识库与向量模型" tabindex="-1">知识库与向量模型 <a class="header-anchor" href="#知识库与向量模型" aria-label="Permalink to &quot;知识库与向量模型&quot;">​</a></h2><p>AnythingLLM 的聊天模型和向量模型是两类配置。接入聊天模型后，如果要上传文档并做问答，还要配置 embedding。</p><p>处理顺序：</p><ol><li>先让普通聊天跑通。</li><li>再配置 embedding 模型。</li><li>上传一个小文档测试检索。</li><li>最后再导入较大的知识库。</li></ol><p>不要一开始就导入大量文件。这样排查问题会很慢，也容易把聊天模型问题和向量模型问题混在一起。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><ol><li>在 AnythingLLM 新建一个测试 Workspace。</li><li>发送“只回复 ok”。</li><li>打开 Tokeness 使用日志，确认请求进入。</li><li>上传一份小文本文件。</li><li>问一个文件中能直接找到答案的问题。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>保存 Provider 后聊天仍走旧模型</td><td>检查 Workspace 是否覆盖了全局模型</td></tr><tr><td>401</td><td>检查 API Key</td></tr><tr><td>404</td><td>Base URL 应为 <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>从 Tokeness 模型广场复制完整模型名</td></tr><tr><td>聊天可用，文档问答不可用</td><td>单独配置 embedding 模型</td></tr><tr><td>回复很慢</td><td>先用短问题测试，再检查模型、上下文长度和文档大小</td></tr></tbody></table><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://docs.anythingllm.com/setup/llm-configuration/cloud/openai-generic" target="_blank" rel="noreferrer">AnythingLLM OpenAI Generic LLM</a></li><li><a href="https://docs.anythingllm.com/configuration" target="_blank" rel="noreferrer">AnythingLLM Configuration</a></li></ul>',25)])])}const k=e(n,[["render",d]]);export{L as __pageData,k as default};
